import { printHTML } from '../../utils/printHelper';
import { primaryActionButtonStyle, primaryActionBtnEnter, primaryActionBtnLeave } from './primaryActionButtonStyle';
// PrintCertificat.jsx
const GMT_LOGO  = 'data:image/png;base64,';
const CERT_LOGO = 'data:image/jpeg;base64,';

function buildCertificatHTML(fiche, form, variant) {
  var cert = form || {};
  var v = variant || {};
  var fmt = function(d){ return d ? new Date(d).toLocaleDateString('fr-FR') : ''; };
  var today = fmt(new Date());
  var contenu = cert.description || '';
  var col = v.color || '#1e3a5f';
  var gmtLogo = v.gmtLogoSrc || GMT_LOGO;
  var certLogo = v.certLogoSrc || CERT_LOGO;
  var headerLeft = v.headerLeft || 'Groupement de Médecine<br/>du Travail de Monastir';
  var headerRight = v.headerRight || 'مجمع طب الشغل<br/>بالمنستير';
  var dateCity = v.dateCity || 'Monastire';
  var arabicDateLine = v.arabicDateLine || 'في المنستير';
  var footerBody = v.footerFr
    ? '<div class="footer-mid footer-legacy" style="text-align:center;line-height:1.6;">' + v.footerFr + '</div>'
    : '<div class="footer-mid">' +
        '<div class="footer-row">' +
          '<span class="footer-left footer-addr-ar" dir="rtl">صندوق بريد رقم 41 - مركز بريد المحطة - المنستير 5079</span>' +
          '<span class="footer-right" dir="rtl">الهاتف : Tél : 73 508 100</span>' +
        '</div>' +
        '<div class="footer-row">' +
          '<span class="footer-left" dir="ltr">Boite Postal N°41 - Poste Gare Monastir - 5079</span>' +
          '<span class="footer-right footer-fax" dir="ltr">Fax : 73 508 101 :الفاكس</span>' +
        '</div>' +
      '</div>';

  return '<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"/>' +
  '<title>Certificat</title>' +
  '<style>' +
  '@page{size:A4 portrait;margin:15mm 18mm 15mm 18mm;}' +
  '*{box-sizing:border-box;margin:0;padding:0;}' +
  'body{font-family:Arial,sans-serif;font-size:10.5pt;color:' + col + ';background:white;display:flex;flex-direction:column;min-height:260mm;print-color-adjust:exact;-webkit-print-color-adjust:exact;}' +
  '.header{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;border-bottom:2px solid ' + col + ';padding-bottom:10px;}' +
  '.header-left{font-size:9.5pt;font-weight:bold;line-height:1.7;}' +
  '.header-center{text-align:center;flex:1;}' +
  '.header-right{font-size:9.5pt;font-weight:bold;line-height:1.7;direction:rtl;text-align:right;}' +
  '.date-line{font-size:10pt;font-weight:bold;margin:14px 0 24px;text-align:center;}' +
  '.content-area{flex:1;font-size:10.5pt;line-height:1.8;white-space:pre-wrap;min-height:160mm;}' +
  '.footer{margin-top:auto;border-top:1.5px solid ' + col + ';padding-top:6px;display:flex;align-items:center;justify-content:center;width:100%;max-width:100%;font-size:10pt;color:' + col + ';-webkit-text-size-adjust:100%;text-size-adjust:100%;}' +
  '.footer-inner{display:flex;flex-direction:row;align-items:center;justify-content:center;flex-wrap:wrap;gap:6px;width:auto;max-width:100%;}' +
  '.footer-mid{flex:0 1 auto;min-width:0;max-width:100%;font-weight:700;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:0;margin:0;padding:0;min-height:40px;text-align:center;}' +
  '.footer-row{display:flex;justify-content:center;align-items:center;flex-wrap:wrap;width:100%;min-width:0;margin:0;padding:0;line-height:1.15;column-gap:12px;row-gap:3px;font-size:10pt;text-align:center;}' +
  '.footer-left{flex:0 1 auto;min-width:0;text-align:center;}' +
  '.footer-addr-ar{text-align:center;}' +
  '.footer-right{flex:0 1 auto;min-width:0;text-align:center;white-space:normal;}' +
  '</style></head><body>' +

  '<div class="header">' +
    '<div class="header-left">' + headerLeft + '</div>' +
    '<div class="header-center">' +
      '<img src="' + gmtLogo + '" style="height:120px;width:auto;display:block;margin:0 auto;" alt="GMT"/>' +
      '<div style="font-size:8pt;margin-top:2px;">Certifié ISO 9001:2008</div>' +
    '</div>' +
    '<div class="header-right">' + headerRight + '</div>' +
  '</div>' +

  '<div class="date-line">' + dateCity + ' le ...... ' + today + ' ...... ' + arabicDateLine + '</div>' +

  '<div class="content-area">' + contenu + '</div>' +

  '<div class="footer">' +
      '<div class="footer-inner">' +
      '<img src="' + certLogo + '" style="height:40px;width:auto;flex-shrink:0;object-fit:contain;display:block;" alt="cert"/>' +
      footerBody +
      '</div>' +
  '</div>' +

  '</body></html>';
}

export default function PrintCertificat({ fiche, form, label, title, variant }) {
  var btnLabel = label || 'Imprimer le certificat';
  var btnTitle = title || btnLabel;
  function handlePrint() {
    var html = buildCertificatHTML(fiche, form, variant);
    printHTML(html);
  }
  return (
    <button onClick={handlePrint} title={btnTitle}
      style={primaryActionButtonStyle()}
      onMouseEnter={primaryActionBtnEnter}
      onMouseLeave={primaryActionBtnLeave}>
      <svg width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
        <path d="M6 9V2h12v7M6 18H4a2 2 0 01-2-2v-5a2 2 0 012-2h16a2 2 0 012 2v5a2 2 0 01-2 2h-2"/>
        <rect x="6" y="14" width="12" height="8"/>
      </svg>
      {btnLabel}
    </button>
  );
}